configuration.content:
const r = $memory.getJson('repuestosResult', {});
const accion = (r.accion || 'continuar').toLowerCase();
$memory.set('accion_repuestos', accion);
if (r.placa_vehiculo) $memory.set('placa_vehiculo', String(r.placa_vehiculo));
if (r.repuesto_solicitado) $memory.set('repuesto_solicitado', String(r.repuesto_solicitado));
if (r.ciudad) $memory.set('ciudad_usuario', String(r.ciudad));
if (r.opcion_checkout) $memory.set('opcion_checkout', String(r.opcion_checkout));
